# Household-level join key -- use these columns together to merge levels.
# (This is what "Common-ID" decomposes into; do NOT join on sample_hhld_no
# alone, it's only unique within a given fsu/sector/state combination.)
HOUSEHOLD_ID_COLUMNS = [
    'fsu_serial_no', 'sector', 'state', 'nss_region', 'district',
    'stratum', 'sub_stratum', 'panel', 'sub_sample', 'fod_sub_region',
    'sample_su_no', 'sample_sub_division_no', 'second_stage_stratum_no',
    'sample_hhld_no',
]


def load_level(level: int, filepath: str, **read_csv_kwargs) -> pd.DataFrame:
    """
    Load a single HCES level CSV and rename its columns using COLUMN_NAMES.

    Raises a clear error if the column count doesn't match what's expected --
    a mismatch usually means the file isn't what you think it is, so this
    deliberately does NOT silently rename in that case.
    """
    if level not in COLUMN_NAMES:
        raise ValueError(f"Level {level} is not a recognized HCES level (expected 1-15).")

    df = pd.read_csv(filepath, **read_csv_kwargs)
    expected = COLUMN_NAMES[level]

    if len(df.columns) != len(expected):
        raise ValueError(
            f"Level {level}: expected {len(expected)} columns based on the "
            f"official layout, but the file has {len(df.columns)}. "
            f"Open the file and check its structure before proceeding -- "
            f"this usually means the file isn't what you expected, or the "
            f"portal changed its export format."
        )

    df.columns = expected
    return df


